+struct HeldCuePeer {
+    release: Option<std::sync::mpsc::Sender<()>>,
+    thread: Option<std::thread::JoinHandle<()>>,
+}
+
+impl HeldCuePeer {
+    fn new(peer: &UnixDatagram) -> Self {
+        let copy = peer.try_clone().unwrap();
+        let (ready_send, ready) = std::sync::mpsc::channel();
+        let (release, released) = std::sync::mpsc::channel();
+        let thread = std::thread::spawn(move || {
+            ready_send
+                .send(())
+                .expect("cue copy ownership acknowledgement");
+            released
+                .recv()
+                .expect("cue copy needs an explicit release message");
+            drop(copy);
+        });
+        let held = Self {
+            release: Some(release),
+            thread: Some(thread),
+        };
+        ready
+            .recv_timeout(Duration::from_secs(5))
+            .expect("cue copy ownership was not acknowledged");
+        held
+    }
+
+    fn release_and_join(&mut self) -> Result<(), &'static str> {
+        let Some(thread) = self.thread.take() else {
+            return Ok(());
+        };
+        let release_ok = self
+            .release
+            .take()
+            .is_some_and(|release| release.send(()).is_ok());
+        let joined = thread.join().is_ok();
+        let _ = std::io::Write::write_fmt(
+            &mut std::io::stderr(),
+            format_args!("cue_copy_cleanup: explicit_release={release_ok} joined={joined}\n"),
+        );
+        if !release_ok {
+            Err("cue copy did not accept explicit release")
+        } else if !joined {
+            Err("cue copy thread panicked")
+        } else {
+            Ok(())
+        }
+    }
+}
+
+impl Drop for HeldCuePeer {
+    fn drop(&mut self) {
+        let _ = self.release_and_join();
+    }
+}
+
+fn with_held_cue_peer(peer: UnixDatagram, run: impl FnOnce(UnixDatagram, &mut HeldCuePeer)) {
+    let mut held = HeldCuePeer::new(&peer);
+    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
+        run(peer, &mut held);
+    }));
+    let cleanup = held.release_and_join();
+    match outcome {
+        Ok(()) => cleanup.expect("cue copy cleanup failed"),
+        Err(original) => std::panic::resume_unwind(original),
+    }
+}
